// Copies the phase-03 reference vectors (generated by an independent Python implementation) into
// relay/test/vectors so the Worker tests can import them through the bundler (no filesystem access
// inside workerd). `test/vector-sync.test.ts` fails if the copy drifts from the source.
//
// Usage: node scripts/sync-vectors.mjs
import { copyFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, '../../server/modules/remote/tests/vectors/derivation.json');
const target = resolve(here, '../test/vectors/derivation.json');

mkdirSync(dirname(target), { recursive: true });
copyFileSync(source, target);
console.log(`synced ${source} -> ${target}`);
